481	                  <FooterLinkColumn key={title} title={title} links={links} />
482	                ))}
483	              </div>
484	            </div>
485	          </div>
486	
487	          {/*
488	            .footer-legal-wrapper:
489	              gap 9px, justify-content center, align-items center, margin-top 20px, display flex
490	              at 767px: flex-col, justify-content flex-start, align-items center
491	          */}
492	          <div className="mt-5 flex items-center justify-center gap-[9px] max-[767px]:flex-col max-[767px]:items-center">
493	            {/*
494	              .copyright-outer:
495	                gap 10px, bg #113569, border-radius 10px, flex 0 auto,
496	                justify-content center, align-items center, padding 4px 15px, display flex
497	                at 991px: padding 3px 10px
498	            */}
499	            <div
500	              className="flex shrink-0 items-center justify-center gap-[10px] rounded-[10px] px-[15px] py-[4px] max-[991px]:px-[10px] max-[991px]:py-[3px]"
501	              style={{ backgroundColor: "#113569" }}
502	            >
503	              {/* .copyright-text: color #fff, font-size 16px, line-height 24px */}
504	              <p className="m-0 text-[16px] leading-6 text-white">
505	                Designed with ❤️ from India
506	              </p>
507	              {/* .indian-flag: width 18px, height 18px, margin-top 3px */}
508	              <Image
509	                src="/images/webflow/🇮🇳.svg"
510	                alt="Indian National flag icon"
511	                width={18}
512	                height={18}
513	                className="mt-[3px] h-[18px] w-[18px]"
514	                onError={() => undefined}
515	              />
516	            </div>
517	          </div>
518	        </div>
519	      </div>
520	    </footer>
521	  );
522	}
