"use client";

import Link from "next/link";
import { useState } from "react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { NAV_ITEMS, CTA_NAV } from "@/lib/constants/navigation";
import type { NavItem } from "@/types/navigation";

/*
  Mobile nav (.nav-23-menu at max-width 767px):
  - Background: #082753 (Webflow navy)
  - Nav links: color #fff, border-bottom 1px solid rgba(255,255,255,0.04), padding 12px 0
  - Dropdown arrow: color #21cfff
  - .nav-23-dropdown-toggle: justify-content space-between, padding 12px 0
  Sheet replaces Webflow's native overlay — same colour palette, same structure.
*/

function ChevronDownIcon({ rotated }: { rotated: boolean }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="16"
      height="16"
      viewBox="0 0 24 24"
      fill="none"
      style={{
        color: "#21cfff",
        transform: rotated ? "rotate(180deg)" : "rotate(0deg)",
        transition: "transform 0.2s ease",
        flexShrink: 0,
      }}
    >
      <path
        d="M11.9997 13.1714L16.9495 8.22168L18.3637 9.63589L11.9997 15.9999L5.63574 9.63589L7.04996 8.22168L11.9997 13.1714Z"
        fill="currentColor"
      />
    </svg>
  );
}

function MobileNavGroup({
  item,
  onNavigate,
}: {
  item: NavItem;
  onNavigate: () => void;
}) {
  const [expanded, setExpanded] = useState(false);

  const rowBorder: React.CSSProperties = {
    borderBottom: "1px solid rgba(255,255,255,0.04)",
  };

  if (!item.children) {
    return (
      /* .nav-23-link at 767px: color #fff, border-bottom 1px solid rgba(255,255,255,0.04), padding 12px 0 */
      <Link
        href={item.href}
        onClick={onNavigate}
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "flex-start",
          padding: "12px 0",
          fontSize: "15px",
          fontWeight: 500,
          color: "#fff",
          textDecoration: "none",
          ...rowBorder,
        }}
      >
        {item.label}
      </Link>
    );
  }

  return (
    <div style={rowBorder}>
      {/* .nav-23-dropdown-toggle at 767px: justify-content space-between, padding 12px 0 */}
      <button
        type="button"
        onClick={() => setExpanded(!expanded)}
        style={{
          display: "flex",
          width: "100%",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "12px 0",
          fontSize: "15px",
          fontWeight: 500,
          color: "#fff",
          background: "none",
          border: "none",
          cursor: "pointer",
        }}
      >
        {item.label}
        <ChevronDownIcon rotated={expanded} />
      </button>

      {expanded && (
        /* .nav-23-dropdown-list.w--open at 767px: position static, padding-top 4px, padding-bottom 4px */
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            paddingTop: "4px",
            paddingBottom: "8px",
          }}
        >
          {item.children.map((child) => {
            const comingSoonBadge = child.comingSoon ? (
              /* .header-comingsoon-badge */
              <span
                style={{
                  color: "#1890ff",
                  backgroundColor: "#e6f7ff",
                  border: "1px solid #91d5ff",
                  borderRadius: "4px",
                  padding: "3px 6px",
                  fontSize: "9px",
                  fontWeight: 700,
                  lineHeight: "1em",
                  display: "inline-flex",
                  alignItems: "center",
                  marginLeft: "6px",
                  whiteSpace: "nowrap",
                }}
              >
                Coming Soon
              </span>
            ) : null;

            const innerContent = (
              <span style={{ display: "flex", alignItems: "center" }}>
                <span
                  style={{
                    fontSize: "14px",
                    fontWeight: 500,
                    color: "rgba(255,255,255,0.9)",
                  }}
                >
                  {child.label}
                </span>
                {comingSoonBadge}
              </span>
            );

            const itemStyle: React.CSSProperties = {
              display: "flex",
              alignItems: "center",
              borderRadius: "8px",
              padding: "10px 12px",
              textDecoration: "none",
              transition: "background-color 0.15s",
            };

            if (child.comingSoon) {
              return (
                <div
                  key={child.label}
                  style={{ ...itemStyle, opacity: 0.5, cursor: "default" }}
                >
                  {innerContent}
                </div>
              );
            }

            if (child.external) {
              return (
                <a
                  key={child.label}
                  href={child.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  onClick={onNavigate}
                  style={itemStyle}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.backgroundColor = "rgba(255,255,255,0.05)";
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.backgroundColor = "transparent";
                  }}
                >
                  {innerContent}
                </a>
              );
            }

            return (
              <Link
                key={child.label}
                href={child.href}
                onClick={onNavigate}
                style={itemStyle}
                onMouseEnter={(e) => {
                  e.currentTarget.style.backgroundColor = "rgba(255,255,255,0.05)";
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.backgroundColor = "transparent";
                }}
              >
                {innerContent}
              </Link>
            );
          })}
        </div>
      )}
    </div>
  );
}

